$req = [Net.HttpWebRequest]::Create("https://ristix.bdo-ki.com"); try { $res = $req.GetResponse() } catch { $res = $_.Exception.Response }; $cert = $req.ServicePoint.Certificate; $cert2 = [System.Security.Cryptography.X509Certificates.X509Certificate2]$cert; Write-Host "Subject:" $cert2.Subject; Write-Host "Expiry:" $cert2.GetExpirationDateString(); Write-Host "SAN:" ($cert2.Extensions | Where-Object {$_.Oid.FriendlyName -eq "Subject Alternative Name"} | ForEach-Object {$_.Format(0)})
